Tool response:
Tool: get_shipment_by_po_number
Description: Retrieve shipment details by purchase order number
Parameters:
    {
      "type": "object",
      "properties": {
        "po_number": {
          "type": "string",
          "description": "Purchase Order number of the shipment",
          "title": "Po Number"
        }
      },
      "required": [
        "po_number"
      ]
    }

Tool response:
Tool: get_nmfc_item_by_code_and_edition
Description: Fetch the NMFC item details using item code and edition ID to validate commodity description and freight class.
Parameters:
    {
      "type": "object",
      "properties": {
        "item_code": {
          "type": "string",
          "description": "NMFC item code",
          "title": "Item Code"
        },
        "edition_id": {
          "type": "integer",
          "description": "ID of the NMFC edition",
          "title": "Edition Id"
        }
      },
      "required": [
        "item_code",
        "edition_id"
      ]
    }

Tool response:
Tool: normalize_shipment
Description: Update the freight class of a shipment after validating against the latest NMFC edition.
Parameters:
    {
      "type": "object",
      "properties": {
        "shipment_id": {
          "type": "integer",
          "description": "Internal ID of the shipment to normalize",
          "title": "Shipment Id"
        }
      },
      "required": [
        "shipment_id"
      ]
    }
